INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, task_xp_total, colleague_name, colleague_role, content) VALUES ('Biomedical', 'Engineering', 1, 1, 'Stage 1.1 — The Quality Management System', 'Document control, QMS roles, procedure deviation, and document lifecycle.', 550, 550, 'Priya Nair', 'QA Manager', '{"format": "staged", "stage_label": "Stage 1.1", "team_quotes": [{"name": "Priya Nair", "role": "QA Manager", "avatar": "PN", "quote": "Document control is the foundation everything else sits on. Get that wrong and the whole DHF is compromised."}, {"name": "Marcus Obi", "role": "Document Controller", "avatar": "MO", "quote": "Knowing who owns what saves hours of confusion. Every role in a QMS exists for a reason."}], "scenario": "Welcome to CardioMed. Your first week. You''ll learn how the Quality Management System works — what it is, who owns what, how documents are controlled, and what happens when shortcuts are taken.", "diagram_label": "Quality Management System — Lifecycle", "stages": [{"id": "t1_1_1", "type": "guided_scenario", "title": "Your First Day", "xp": 100, "colleague": {"name": "Priya Nair", "role": "QA Manager"}, "brief": ["Welcome to the team. Before you touch a single document, you need to understand why we work the way we do. A Quality Management System — or QMS — isn''t bureaucracy for its own sake. It''s the skeleton of everything we do here.", "ISO 13485 is the international standard that defines what a QMS must look like for a medical device company. Unlike general quality standards, ISO 13485 has one overriding purpose: patient safety. Every procedure, every record, every signature exists because somewhere, at some point, a patient''s life may depend on the device we''re building.", "The FDA has its own framework — 21 CFR Part 820 — which overlaps significantly with ISO 13485 but has some important differences. The key principle: if it isn''t documented, it didn''t happen."], "pull_quote": "If it isn''t documented, it didn''t happen.", "scenario": "It''s Monday morning. You''ve been added to the CardioSense Pro project — a Class II implantable cardiac monitor. Your manager asks you to update a design specification. You find two versions on the shared drive — one dated last Thursday, one dated three weeks ago. Neither has a version number visible.", "questions": [{"id": "q1", "kind": "single_best", "prompt": "What is the correct first action?", "options": [{"label": "Check the Document Control system (eQMS) to find the current approved revision.", "correct": true, "feedback": "Exactly right. Under document control, the eQMS holds the approved, current revision. Any copy outside it is potentially obsolete."}, {"label": "Use the most recent date — it must be the latest.", "correct": false, "feedback": "A newer date doesn''t mean controlled status. Engineers sometimes save working copies locally. Always verify in the eQMS."}, {"label": "Ask a colleague which one they''ve been using.", "correct": false, "feedback": "Colleagues may also be using uncontrolled copies. This doesn''t establish controlled status."}, {"label": "Use both versions to cover all changes.", "correct": false, "feedback": "Using two versions creates inconsistency and is a QMS non-conformance."}]}, {"id": "q2", "kind": "rank_steps", "prompt": "A new SOP needs to be created for an incoming inspection process. Put these steps in the correct order.", "items": ["Draft the SOP", "Send for peer review", "QA Manager approves the document", "Document Controller assigns a number and revision", "Training is delivered to relevant staff", "Old procedure (if any) is marked obsolete"], "feedback_correct": "Training always follows approval — never train on a draft. Obsolescence of the old version is the final step, not the first.", "feedback_incorrect": "Training must happen on the approved version. If you train staff on a draft that then changes, they''ve been trained on something that doesn''t exist."}, {"id": "q3", "kind": "classify", "prompt": "Sort these documents into: SOP, Work Instruction (WI), or Form.", "categories": ["SOP", "WI", "Form"], "items": [{"text": "Step-by-step guide for performing ultrasonic welding of CardioSense Pro housing", "category": "WI"}, {"text": "Company-level policy for managing non-conforming product", "category": "SOP"}, {"text": "Incoming inspection checklist for housing components", "category": "Form"}, {"text": "Process for raising and closing a CAPA", "category": "SOP"}, {"text": "Torque settings and sequence for PCB screw assembly", "category": "WI"}, {"text": "Change Request template", "category": "Form"}], "feedback": "SOPs describe the what and why at process level. WIs give the operator precise steps for a specific operation. Forms capture evidence that the procedure was followed."}, {"id": "q4", "kind": "fill_blank", "prompt": "Complete this sentence: \"A ________ is a systematic, independent examination to determine whether quality activities comply with planned arrangements and whether these arrangements are implemented effectively.\"", "answer": "audit", "alternatives": ["audits"], "feedback_correct": "An audit. Internal audits are mandatory under ISO 13485 clause 8.2.4. They are one of the primary tools for finding gaps before a regulatory body does.", "feedback_incorrect": "A review is a scheduled look at data. An audit is independent, systematic, and seeks objective evidence of compliance. The independence is the key distinction."}], "colleague_card": "Priya Nair: \"Document control is the foundation everything else sits on. Get that wrong and the whole DHF is compromised.\""}, {"id": "t1_1_2", "type": "document_builder", "title": "Map the QMS Roles", "xp": 150, "instruction": "Match each scenario statement to the correct role, then write a one-sentence responsibility statement. Your sentence must include the required keywords listed under each scenario.", "reference": {"title": "ISO 13485:2016 Clause 5.5 — Roles, Responsibilities & Authorities", "body": "Top management shall define roles, responsibilities, and authorities for all personnel affecting product quality.\n\nKEY ROLES:\n• QA Manager — owns the QMS, approves all quality documents, signs off CAPAs.\n• R&D / Design Engineer — responsible for design inputs, outputs, V&V, DHF maintenance.\n• Regulatory Affairs Specialist — manages regulatory submissions, advises on classification.\n• Production / Manufacturing Engineer — owns process validation, work instructions.\n• Document Controller — manages the eQMS, assigns document numbers.", "highlights": ["ISO 13485 §5.5", "21 CFR 820.20(b)"]}, "fields": [{"id": "f1", "label": "Lena has received a query from the FDA about the CardioSense Pro 510(k) timeline.", "placeholder": "Role: Regulatory Affairs Specialist. Responsibility: ...", "required_terms": ["Regulatory Affairs", "FDA", "submission", "timeline"], "min_chars": 40}, {"id": "f2", "label": "Tom needs to ensure the verification protocol for the housing drop test is complete before Gate 3.", "placeholder": "Role: R&D / Design Engineer. Responsibility: ...", "required_terms": ["R&D", "verification", "protocol", "design"], "min_chars": 40}, {"id": "f3", "label": "Priya has found that three CAPAs are overdue and needs to escalate.", "placeholder": "Role: QA Manager. Responsibility: ...", "required_terms": ["QA", "CAPA", "escalate", "quality"], "min_chars": 40}, {"id": "f4", "label": "Marcus needs to assign a new document number to the revised Incoming Inspection SOP.", "placeholder": "Role: Document Controller. Responsibility: ...", "required_terms": ["Document Controller", "document number", "eQMS", "revision"], "min_chars": 40}, {"id": "f5", "label": "Victor needs to validate the ultrasonic welding process before full production.", "placeholder": "Role: Production / Manufacturing Engineer. Responsibility: ...", "required_terms": ["Manufacturing", "process validation", "production"], "min_chars": 40}, {"id": "f6", "label": "Sarah needs to update the BOM to reflect the new battery specification.", "placeholder": "Role: R&D / Design Engineer. Responsibility: ...", "required_terms": ["R&D", "BOM", "design", "specification"], "min_chars": 40}], "dhf": {"doc_code": "QMS-ROLES-001", "doc_title": "QMS Roles and Responsibilities — CardioSense Pro", "doc_section": "Quality Management System"}, "colleague_card": {"name": "Marcus Obi", "role": "Document Controller", "avatar": "MO", "quote": "Knowing who owns what saves hours of confusion. Every role in a QMS exists for a reason."}}, {"id": "t1_1_3", "type": "decision_sandbox", "title": "Procedure Deviation", "xp": 200, "scenario": "A batch of 50 CardioSense Pro housings arrived. 8 have a small scratch on the inner mating surface. The incoming inspection procedure says: \"Any surface defect on internal mating surfaces is cause for rejection.\" A colleague says: \"Just use the 42 good ones and don''t log the defective ones.\"", "nodes": [{"id": "n1", "prompt": "What do you do with the 8 scratched housings?", "options": [{"label": "Set aside the 8 and log only the 42 acceptable ones.", "outcome": "wrong", "consequence": "Three weeks later, an auditor reviews the receipt records. The receipt quantity (42) doesn''t match the delivery note (50). She asks what happened to the other 8. No record exists. This is falsification of quality records — a Major finding."}, {"label": "Quarantine all affected units and raise an NCR for the 8.", "outcome": "correct", "consequence": "Correct. The 8 units enter formal Non-Conformance handling, fully traceable."}, {"label": "Use all 50 — the scratches are cosmetic.", "outcome": "wrong", "consequence": "Two units fail the hermetic seal test in production because the scratch interferes with the ultrasonic weld. Root cause traces back to incoming inspection. A CAPA is raised against you."}]}, {"id": "n2", "prompt": "How do you write the NCR?", "options": [{"label": "\"8 housings rejected — defective.\"", "outcome": "wrong", "consequence": "The NCR is too vague to support root cause analysis. Priya will send it back for rework."}, {"label": "\"8 of 50 units received from PrecisionMed Ltd on [date] exhibit surface scratches on internal mating surface. Defect location: inner cavity. Affected part number: CS-HSG-001 Rev C. Disposition: quarantine pending review.\"", "outcome": "correct", "consequence": "Strong NCR. Specific, traceable, supports root-cause investigation."}, {"label": "Take a photo and email the supplier.", "outcome": "wrong", "consequence": "Email isn''t a controlled quality record. It won''t appear in the eQMS and can''t be audited."}]}, {"id": "n3", "prompt": "The supplier wants to discuss. What next?", "options": [{"label": "Accept a credit note and reorder.", "outcome": "wrong", "consequence": "Doesn''t address root cause. The same defect will recur in the next shipment."}, {"label": "Request a Supplier Corrective Action (SCAR) and ask them to investigate the moulding process.", "outcome": "correct", "consequence": "Right. SCAR drives the supplier to investigate root cause and prevent recurrence."}, {"label": "Remove the supplier from the Approved Supplier List immediately.", "outcome": "wrong", "consequence": "Premature without investigation. Disqualification needs evidence of repeated non-conformance."}]}], "debrief": {"flow": ["Quarantine 8 units", "Raise NCR with full detail", "Request SCAR from supplier", "Update incoming inspection log", "Notify QA Manager", "Close NCR once replacement stock received and inspected"], "text": "The correct path protects traceability at every step. Your QMS procedures are a safety net — bypassing them doesn''t make problems disappear, it makes them invisible until an audit or a patient safety event."}, "colleague_card": "Priya Nair: \"Someone always suggests the shortcut. Your job is to know why the long way is the right way.\""}, {"id": "t1_1_4", "type": "guided_scenario", "title": "Document Control 101", "xp": 100, "colleague": {"name": "Marcus Obi", "role": "Document Controller"}, "brief": ["Every document in our QMS has a lifecycle: created, reviewed, approved, used, revised, and made obsolete. My job is to make sure every step is controlled and traceable.", "Document numbering follows a convention: [Department Code]-[Document Type]-[Sequential Number]-[Revision]. For example, QA-SOP-0012-Rev B is the Quality department''s twelfth SOP, currently at revision B. Never refer to a document by name alone — always by number and revision.", "The golden rule: only work from the current approved revision in the eQMS. A printed copy is uncontrolled the moment it leaves the printer. If you must print, stamp it ''UNCONTROLLED COPY'' and never use it to make decisions."], "pull_quote": "Only work from the current approved revision.", "scenario": "You need to follow the Calibration SOP to send a torque wrench for calibration. You find a printed copy on the bench. It''s stamped \"UNCONTROLLED COPY — Rev D.\" The eQMS shows the current version is Rev F.", "questions": [{"id": "q1", "kind": "single_best", "prompt": "What do you do?", "options": [{"label": "Access the current Rev F in the eQMS and follow that version. Discard the Rev D printout.", "correct": true, "feedback": "Right. Only work from the current approved revision."}, {"label": "Follow Rev D — it''s probably the same.", "correct": false, "feedback": "''Probably'' isn''t good enough in a QMS. Procedures change for reasons."}, {"label": "Follow both and use whichever seems more practical.", "correct": false, "feedback": "Choosing between procedure versions is not authorised."}, {"label": "Ask a colleague which revision they normally use.", "correct": false, "feedback": "The eQMS is authoritative, not peer opinion."}]}, {"id": "q2", "kind": "fill_blank", "prompt": "A new form is created: the Quality department''s 3rd form, first revision. Using the convention [Dept]-[Type]-[Seq]-[Rev], what is the correct document number?", "answer": "QA-FORM-0003-Rev A", "alternatives": ["QA-FORM-0003-RevA", "QA FORM 0003 Rev A"], "feedback_correct": "The first revision of any new document is always Rev A. Only when revised for the first time does it become Rev B.", "feedback_incorrect": "First revision is always Rev A. The format is [Dept]-[Type]-[Seq]-[Rev] → QA-FORM-0003-Rev A."}, {"id": "q3", "kind": "classify", "prompt": "Sort these into: Controlled Document (lives in eQMS, has revision history) or Reference Only (informational, not controlled).", "categories": ["Controlled", "Reference Only"], "items": [{"text": "Incoming Inspection SOP", "category": "Controlled"}, {"text": "ISO 13485 standard (purchased copy)", "category": "Reference Only"}, {"text": "CardioSense Pro Bill of Materials", "category": "Controlled"}, {"text": "Industry journal article on cardiac monitoring", "category": "Reference Only"}, {"text": "Calibration Certificate for torque wrench", "category": "Controlled"}, {"text": "Training video on GD&T basics", "category": "Reference Only"}, {"text": "CAPA Report for housing crack issue", "category": "Controlled"}], "feedback": "Controlled documents directly govern how work is done or provide objective evidence. Calibration certificates ARE controlled records — they prove your measuring equipment is valid."}, {"id": "q4", "kind": "rank_steps", "prompt": "A document is being revised because a process changed. Put the revision lifecycle in order.", "items": ["Engineer identifies the SOP needs updating", "Engineer drafts the revised content", "Peer review by another qualified engineer", "QA Manager reviews and approves", "Document Controller assigns new revision letter and uploads to eQMS", "Previous revision is made obsolete in eQMS", "Affected staff are trained on the new revision", "Training records are filed in eQMS"], "feedback_correct": "Approval before training, always. Training records close the loop.", "feedback_incorrect": "Training must happen on the approved version, not a draft. Always approve first."}], "colleague_card": "Marcus Obi: \"I''ve seen companies fail a notified body audit purely on document control housekeeping. Don''t let that be us.\""}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, task_xp_total, colleague_name, colleague_role, content) VALUES ('Biomedical', 'Engineering', 1, 2, 'Stage 1.2 — Regulatory Landscape', 'FDA, EU MDR, TGA classification and a Risk Classification Matrix.', 625, 625, 'Lena Park', 'RA Specialist', '{"format": "staged", "stage_label": "Stage 1.2", "team_quotes": [{"name": "Lena Park", "role": "RA Specialist", "avatar": "LP", "quote": "The best engineers understand the regulatory context of every design decision they make."}, {"name": "Tom Hargreaves", "role": "R&D Lead", "avatar": "TH", "quote": "Risk estimation is always a judgement call — but it must be a documented, defensible one."}], "scenario": "Lena Park, your Regulatory Affairs Specialist, walks you through the FDA, EU MDR and TGA frameworks — then asks you to classify devices, write the strategy summary, and build the first risk matrix for the CardioSense Pro.", "diagram_label": "Regulatory Landscape — FDA / EU MDR / TGA", "stages": [{"id": "t1_2_1", "type": "guided_scenario", "title": "Regulatory Frameworks", "xp": 100, "colleague": {"name": "Lena Park", "role": "RA Specialist"}, "brief": ["Regulatory affairs is what stands between your device and it reaching a patient. Every country has its own framework. In the US, the FDA governs medical devices under 21 CFR Part 820.", "Devices are Class I (low risk), Class II (moderate risk), or Class III (high risk). Most Class II devices go through a 510(k) — demonstrating substantial equivalence to a predicate device. Class III devices require a PMA with clinical trial data.", "In Europe, the EU MDR (2017/745) replaced the old MDD. It''s stricter — stronger clinical evidence requirements, mandatory post-market clinical follow-up. In Australia, the TGA mirrors EU frameworks closely. The key insight: the same device may face different regulatory pathways in different markets."], "pull_quote": "The same device may face different regulatory pathways in different markets.", "scenario": "The CardioSense Pro is an implantable cardiac monitor that continuously records ECG data and wirelessly transmits it to a clinician''s app. It has no therapeutic function — it only monitors and records.", "questions": [{"id": "q1", "kind": "single_best", "prompt": "Under FDA classification rules, what class is the CardioSense Pro most likely to be?", "options": [{"label": "Class II — a non-therapeutic monitoring device with moderate risk, likely requiring a 510(k) if a predicate device exists.", "correct": true, "feedback": "Right. Implantable cardiac monitors that only record and transmit are Class II with 510(k) pathway."}, {"label": "Class I — it doesn''t treat anything so it''s low risk.", "correct": false, "feedback": "Implantable devices are never Class I. The implantation itself carries risk."}, {"label": "Class III — any implant is automatically Class III.", "correct": false, "feedback": "Classification depends on risk profile and intended use, not just the delivery route."}, {"label": "It doesn''t need classification — it''s a monitoring device.", "correct": false, "feedback": "All medical devices sold in regulated markets must be classified."}]}, {"id": "q2", "kind": "classify", "prompt": "Match each regulatory action to the correct pathway: 510(k), PMA, or CE Mark.", "categories": ["510(k)", "PMA", "CE Mark"], "items": [{"text": "A new coronary stent — first of its kind, no predicate", "category": "PMA"}, {"text": "A blood glucose monitor substantially equivalent to one on market", "category": "510(k)"}, {"text": "A cardiac pacemaker for the EU market", "category": "CE Mark"}, {"text": "A Class II cardiac monitor with a valid predicate device", "category": "510(k)"}, {"text": "A transcatheter heart valve (Class III) for US market", "category": "PMA"}, {"text": "A wound dressing for the EU market", "category": "CE Mark"}], "feedback": "510(k) relies on substantial equivalence to a predicate. PMA is for Class III with no 510(k) pathway. CE Mark applies to the EU market regardless of US classification."}, {"id": "q3", "kind": "single_best", "prompt": "The EU MDR replaced the EU MDD. What was the primary driver?", "options": [{"label": "Several high-profile device failures (including the PIP breast implant scandal) revealed gaps in pre-market scrutiny and post-market surveillance under the MDD. The MDR introduced stronger clinical evidence requirements and stricter notified body oversight.", "correct": true, "feedback": "Right. PIP-style failures drove the strengthening of pre-market and post-market requirements."}, {"label": "The MDD had no clinical evaluation requirements at all.", "correct": false, "feedback": "The MDD did require clinical evaluation. The MDR significantly strengthened what must be demonstrated."}, {"label": "EU manufacturers wanted to make exporting to the US easier.", "correct": false, "feedback": "EU and US frameworks remain separate. MDR was not designed to align with FDA."}, {"label": "The change was primarily administrative.", "correct": false, "feedback": "MDR introduced substantive new requirements. Many Class IIa devices moved to Class IIb or III."}]}, {"id": "q4", "kind": "fill_blank", "prompt": "Under EU MDR, the organisation responsible for independently assessing a manufacturer''s technical documentation before issuing a CE Mark is called a ________.", "answer": "Notified Body", "alternatives": ["notified body", "Notified body"], "feedback_correct": "Notified Bodies are independent conformity assessment organisations designated by EU member states. Examples include BSI, TÜV SÜD, and SGS.", "feedback_incorrect": "The correct term is Notified Body — an independent EU-designated conformity-assessment organisation."}, {"id": "q5", "kind": "single_best", "prompt": "The CardioSense Pro will be sold in the US, EU, and Australia. Which statement best describes the regulatory strategy?", "options": [{"label": "Each market requires a separate submission/registration process, but harmonised standards (ISO 13485, ISO 14971) provide a common quality and safety framework that satisfies all three regulators.", "correct": true, "feedback": "Right. Separate submissions, but harmonised standards underpin them all."}, {"label": "FDA approval automatically covers EU and Australia.", "correct": false, "feedback": "No automatic mutual recognition exists."}, {"label": "Once CE Mark is obtained, FDA clearance follows automatically.", "correct": false, "feedback": "FDA and EU MDR are entirely separate processes."}, {"label": "The three markets have identical requirements so only one submission is needed.", "correct": false, "feedback": "Requirements overlap significantly but are not identical."}]}], "colleague_card": "Lena Park: \"The best engineers understand the regulatory context of every design decision they make. It changes how you write design inputs, what tests you run, and how you write your reports.\""}, {"id": "t1_2_2", "type": "decision_sandbox", "title": "Classify the Device", "xp": 200, "scenario": "Lena asks you to classify four fictional devices using the FDA framework. Each runs as a sequential mini-sandbox.", "nodes": [{"id": "d1", "prompt": "DEVICE 1: A disposable surgical scalpel. Does it sustain or support life?", "options": [{"label": "No — it''s a single-use, well-understood instrument with low risk → Class I.", "outcome": "correct", "consequence": "Class I. Disposable surgical scalpels are Class I exempt — well-understood risks controlled by general QMS requirements."}, {"label": "Yes — any sharp instrument is high risk → Class III.", "outcome": "wrong", "consequence": "Sharpness alone doesn''t drive classification. Risk is judged on intended use and consequence of failure."}, {"label": "It''s exempt from all classification.", "outcome": "wrong", "consequence": "No device sold into a regulated market is exempt from classification — even Class I exempt requires registration."}]}, {"id": "d2", "prompt": "DEVICE 2: The CardioSense Pro. It''s implantable and records/transmits ECG — but does not pace or defibrillate. What class?", "options": [{"label": "Class II — implantable monitor that only records and transmits. Predicate exists (e.g. Medtronic LINQ). 510(k) pathway.", "outcome": "correct", "consequence": "Class II. The 510(k) pathway applies because there''s a predicate device with similar intended use and technological characteristics."}, {"label": "Class I — it''s only a monitor.", "outcome": "wrong", "consequence": "Implantable devices are never Class I. The implantation itself carries risk."}, {"label": "Class III — any cardiac implant is Class III.", "outcome": "wrong", "consequence": "Only life-sustaining cardiac implants (pacemakers, ICDs) are Class III. Monitors are Class II."}]}, {"id": "d3", "prompt": "DEVICE 3: A transcatheter aortic valve replacement (TAVR). What class?", "options": [{"label": "Class III — replaces a heart valve, sustains life. PMA required.", "outcome": "correct", "consequence": "Class III. TAVR devices sustain life, so PMA with extensive clinical trial data is required."}, {"label": "Class II — it''s a structural device.", "outcome": "wrong", "consequence": "Life-sustaining devices are always Class III, regardless of structural vs. active classification."}, {"label": "Class I — minimally invasive procedure.", "outcome": "wrong", "consequence": "TAVR replaces a heart valve. Patient survival depends on it."}]}, {"id": "d4", "prompt": "DEVICE 4: A software app that displays ECG data from the CardioSense Pro and flags arrhythmia. What class?", "options": [{"label": "Class II SaMD — incorrect arrhythmia information could delay treatment. Special controls including software validation apply.", "outcome": "correct", "consequence": "Class II Software as a Medical Device (SaMD). FDA''s SaMD framework treats clinical decision-support software as moderate risk."}, {"label": "Not a medical device — it''s just software.", "outcome": "wrong", "consequence": "Software that makes clinical recommendations IS a medical device under FDA''s SaMD framework."}, {"label": "Class III — software that touches patient care.", "outcome": "wrong", "consequence": "Information-display SaMD is Class II. Class III would be software that directly controls a life-sustaining therapy."}]}], "debrief": {"text": "Classification is never a lookup table — it''s a structured risk argument. For each device you must demonstrate intended use, risk to the patient, and whether a predicate exists."}, "colleague_card": "Lena Park: \"Classification is never just a lookup table. You have to think about what happens when it fails and who gets hurt.\""}, {"id": "t1_2_3", "type": "document_builder", "title": "Write a Regulatory Strategy Summary", "xp": 150, "instruction": "Draft RS-001, the internal Regulatory Strategy Summary for the CardioSense Pro. Each field has required keywords your answer must include.", "reference": {"title": "Template — Regulatory Strategy Summary (RS-001)", "body": "A Regulatory Strategy Summary is an internal planning document outlining how a medical device will be brought to market.\n\nKEY ELEMENTS:\n1. Intended use statement — specific, defines patient population and clinical context\n2. Device classification in each target market\n3. Regulatory pathway for each market\n4. Applicable standards (ISO 14971, IEC 60601-1, ISO 13485, IEC 62366-1)\n5. Key risks to the regulatory timeline\n6. Estimated time to first submission", "highlights": ["FDA 21 CFR Part 820", "EU MDR 2017/745", "TGA"]}, "fields": [{"id": "intended_use", "label": "Intended Use Statement", "placeholder": "The CardioSense Pro is intended for use in adult patients (≥18 years) with...", "required_terms": ["adult patients", "arrhythmia", "ECG", "physician"], "min_chars": 80, "help": "Must include patient population, clinical action, and clinical setting."}, {"id": "classification", "label": "Device Classification (US / EU / Australia)", "placeholder": "US (FDA): Class II — 510(k). EU (MDR): Class IIb — Rule 7. Australia (TGA): Class IIb...", "required_terms": ["Class II", "510(k)", "Class IIb", "Rule 7"], "min_chars": 80, "help": "Must identify Class II for US, Class IIb for EU with MDR rule justification."}, {"id": "standards", "label": "Applicable Standards (list at least 4)", "placeholder": "ISO 13485:2016, ISO 14971:2019, IEC 60601-1, IEC 62366-1...", "required_terms": ["ISO 13485", "ISO 14971", "IEC 60601-1", "IEC 62366-1"], "min_chars": 80}, {"id": "risks", "label": "Top 3 Regulatory Risks (device-specific)", "placeholder": "1. No direct predicate with identical sensing algorithm... 2. EU MDR clinical evaluation... 3. SaMD review...", "required_terms": ["predicate", "MDR clinical", "SaMD"], "min_chars": 100, "help": "Each risk must be CardioSense Pro-specific and reference a concrete regulatory mechanism."}, {"id": "timeline", "label": "Estimated Time to First Submission", "placeholder": "US 510(k): 18–24 months from design freeze, assuming predicate confirmed and V&V complete. EU MDR: 24–30 months...", "required_terms": ["510(k)", "design freeze", "Notified Body", "MDR"], "min_chars": 80, "help": "Must differentiate between markets and state at least one conditional assumption."}], "dhf": {"doc_code": "RS-001", "doc_title": "Regulatory Strategy Summary — CardioSense Pro", "doc_section": "Regulatory Correspondence"}, "colleague_card": {"name": "Lena Park", "role": "RA Specialist", "avatar": "LP", "quote": "If the intended use statement is vague or wrong, every regulatory submission built on top of it is compromised."}}, {"id": "t1_2_4", "type": "risk_matrix", "title": "Risk Classification Matrix", "xp": 175, "intro": "ISO 14971 requires estimating the risk of each hazard using Probability (P, 1–5) and Severity (S, 1–5). RPN = P × S. Zones: 1–4 Acceptable, 5–10 ALARP, 12–25 Intolerable.", "formula": "RPN = P \\times S", "hazards": [{"id": "h1", "text": "Wireless transmission fails during a critical arrhythmia event.", "correct_p": 2, "correct_s": 4, "control_keywords": ["local alert", "30 seconds", "log", "transmission failures"], "feedback": {"p_too_high": "A device with redundant wireless hardware and local storage doesn''t fail frequently. Consider engineering controls before assigning raw probability.", "p_too_low": "Hospital RF environments can be hostile. P=1 underestimates real-world transmission failure rate."}}, {"id": "h2", "text": "Subcutaneous housing causes localised tissue reaction due to incompatible material.", "correct_p": 2, "correct_s": 3, "control_keywords": ["ISO 10993-1", "biocompatibility", "implant history"]}, {"id": "h3", "text": "Firmware incorrectly classifies normal sinus rhythm as atrial fibrillation.", "correct_p": 3, "correct_s": 3, "control_keywords": ["validate", "10,000", "annotated", "physician review"]}], "sensitivity": {"hazard_id": "h3", "prompt": "What happens to Hazard 3 RPN if improved firmware validation reduces P from 3 to 1?", "new_p": 1, "explanation": "RPN drops from 9 to 3 — moves from ALARP to Acceptable. This is why risk controls matter: reducing probability can shift a risk from requiring ongoing monitoring to acceptable."}, "colleague_card": "Tom Hargreaves: \"Risk estimation is always a judgement call — but it must be a documented, defensible one. An auditor will ask you to justify every P and S score.\""}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, task_xp_total, colleague_name, colleague_role, content) VALUES ('Biomedical', 'Engineering', 1, 3, 'Stage 1.3 — Design Inputs', 'Writing verifiable design inputs and defending them in a clinical review.', 700, 700, 'Tom Hargreaves', 'R&D Lead', '{"format": "staged", "stage_label": "Stage 1.3", "team_quotes": [{"name": "Tom Hargreaves", "role": "R&D Lead", "avatar": "TH", "quote": "The translation from user need to design input is where most junior engineers struggle."}, {"name": "Priya Nair", "role": "QA Manager", "avatar": "PN", "quote": "Vague design inputs are the single biggest source of downstream delays."}, {"name": "Dr. Anaya Rao", "role": "Clinical Advisor", "avatar": "AR", "quote": "27 days gives clinicians adequate follow-up window. Good catch."}], "scenario": "Tom Hargreaves walks you through what design inputs are, how to write them, what goes wrong when they''re vague, and how to defend them in a review with Clinical and QA.", "diagram_label": "Design Input Workflow — User Need → DHF", "stages": [{"id": "t1_3_1", "type": "guided_scenario", "title": "What Are Design Inputs?", "xp": 100, "colleague": {"name": "Tom Hargreaves", "role": "R&D Lead"}, "brief": ["Design inputs are the requirements your device must meet. They translate fuzzy clinical need into precise, testable engineering specifications. ISO 13485 clause 7.3.3 requires that design inputs be documented, reviewed, and approved.", "The critical rule: every design input must be verifiable. ''The device shall be comfortable'' is not verifiable — comfort is subjective. ''The housing shall not exceed 8mm in thickness and shall weigh less than 12g'' is verifiable with a calliper and a scale.", "Design inputs come from multiple sources: user needs (from clinicians), regulatory requirements (standards you must comply with), business requirements (cost, production), and safety requirements (risk controls from ISO 14971). All of these feed the design input document."], "pull_quote": "Every design input must be verifiable.", "scenario": "Dr. Anaya Rao has sent her clinical requirements: \"It needs to last a long time without charging, be easy to implant, not cause skin problems, and connect reliably to the hospital system.\"", "questions": [{"id": "q1", "kind": "classify", "prompt": "Sort each of Dr. Rao''s statements into: Good design input candidate or Needs translation.", "categories": ["Good design input", "Needs translation"], "items": [{"text": "Last a long time without charging", "category": "Needs translation"}, {"text": "Easy to implant", "category": "Needs translation"}, {"text": "Not cause skin problems", "category": "Needs translation"}, {"text": "Connect reliably to the hospital system", "category": "Needs translation"}], "feedback": "Trick question — none of these are design inputs yet. They''re user needs. Your job is to translate each one into a measurable, verifiable engineering requirement."}, {"id": "q2a", "kind": "fill_blank", "prompt": "\"Last a long time without charging\" → \"The device battery shall support ________ months of continuous operation without recharging.\" Enter a clinically appropriate number (≥12).", "answer": "18", "alternatives": ["12", "24", "36"], "feedback_correct": "Any specific number ≥12 with a unit. 18 months is the CardioSense Pro target.", "feedback_incorrect": "Must be a specific number ≥12. ''Long time'' isn''t a verifiable spec."}, {"id": "q2b", "kind": "fill_blank", "prompt": "\"Not cause skin problems\" → \"All patient-contacting materials shall meet the biocompatibility requirements of ________ for chronic implantation (>30 days).\"", "answer": "ISO 10993-1", "alternatives": ["ISO 10993", "ISO10993-1", "ISO 10993:2018"], "feedback_correct": "ISO 10993-1 is the foundational biocompatibility standard for medical devices.", "feedback_incorrect": "The biocompatibility standard for medical devices is ISO 10993-1."}, {"id": "q3", "kind": "single_best", "prompt": "Which is a correctly written design input?", "options": [{"label": "The device housing shall achieve a minimum ingress protection rating of IPX7 per IEC 60529, verified by immersion testing at 1m depth for 30 minutes.", "correct": true, "feedback": "Quantified, verifiable, references a standard, defines test method."}, {"label": "The device must be water resistant.", "correct": false, "feedback": "No specification level, no standard, no verification method."}, {"label": "The battery life should be acceptable for clinical use.", "correct": false, "feedback": "''Acceptable'' is not defined. Not verifiable."}, {"label": "The device should look professional and be durable.", "correct": false, "feedback": "Two requirements in one sentence, neither measurable."}]}, {"id": "q4", "kind": "rank_steps", "prompt": "Put the design input development process in order.", "items": ["Gather user needs from clinicians and users", "Identify applicable regulatory requirements and standards", "Translate user needs into measurable engineering specifications", "Identify risk control measures that become design inputs", "Review all design inputs for completeness and verifiability", "Obtain formal approval from R&D Lead and QA", "File approved design inputs in the DHF"], "feedback_correct": "Right. Risk controls feed back into the input set before review and approval.", "feedback_incorrect": "Risk controls (Step 4) must be identified before final review. Standards (Step 2) before translation (Step 3)."}], "colleague_card": "Tom Hargreaves: \"The translation from user need to design input is where most junior engineers struggle. It takes clinical empathy and engineering precision simultaneously.\""}, {"id": "t1_3_2", "type": "document_builder", "title": "Write Design Inputs", "xp": 150, "instruction": "Translate each of the 5 user needs below into a quantified, verifiable design input. Each must include the required keywords.", "reference": {"title": "ISO 13485 §7.3.3 — Good Design Input Characteristics", "body": "Every design input must be:\n• Quantified — specific numbers, ranges, units\n• Verifiable — a test method can be defined\n• Unambiguous — only one interpretation\n• Traceable — to a user need, regulatory requirement, or risk control\n• Conflict-free — does not contradict other inputs", "highlights": ["ISO 13485 §7.3.3", "ISO 14971", "IEC 60601-1-2"]}, "fields": [{"id": "un1", "label": "User need 1: \"The device must be comfortable and not too big.\"", "placeholder": "The device housing dimensions shall not exceed 45mm × 10mm × 8mm and total implanted weight shall not exceed 12g.", "required_terms": ["dimensions", "mm", "weight", "g"], "min_chars": 60}, {"id": "un2", "label": "User need 2: \"The data needs to get to the doctor quickly.\"", "placeholder": "The device shall transmit ECG data to the physician portal within 5 minutes of each 24-hour cycle, with minimum 95% success rate under validated RF conditions.", "required_terms": ["transmit", "minutes", "%", "success"], "min_chars": 80}, {"id": "un3", "label": "User need 3: \"It can''t interfere with other hospital equipment.\"", "placeholder": "The device shall comply with electromagnetic compatibility requirements per IEC 60601-1-2:2014 for Group 1, Class B equipment...", "required_terms": ["IEC 60601-1-2", "electromagnetic", "Group 1"], "min_chars": 80}, {"id": "un4", "label": "User need 4: \"It should be safe for patients with metal allergies.\"", "placeholder": "All metallic patient-contacting components shall be manufactured from implant-grade titanium (ASTM F136) or 316L stainless steel (ASTM F138) with no free nickel...", "required_terms": ["titanium", "ASTM F136", "nickel"], "min_chars": 80}, {"id": "un5", "label": "User need 5: \"It needs to record the heart rhythm continuously.\"", "placeholder": "The device shall continuously record a subcutaneous single-lead ECG at a minimum sampling rate of 256 Hz with 0.5–40 Hz frequency response, storing at least 27 days of data...", "required_terms": ["sampling rate", "Hz", "27 days", "ECG"], "min_chars": 100}], "dhf": {"doc_code": "DI-REGISTER-001", "doc_title": "Design Input Register — CardioSense Pro", "doc_section": "Design Inputs"}, "colleague_card": {"name": "Tom Hargreaves", "role": "R&D Lead", "avatar": "TH", "quote": "Notice how each one immediately tells you how you''d test it. That''s the test: can you write the test before you build the thing?"}}, {"id": "t1_3_3", "type": "decision_sandbox", "title": "Incomplete Design Inputs", "xp": 200, "scenario": "During a design review, a colleague presents: \"Design Input DI-007: The battery shall last a long time.\" Priya flags it immediately and turns to you.", "nodes": [{"id": "n1", "prompt": "What''s wrong with DI-007?", "options": [{"label": "Nothing — ''long time'' is understood within the team.", "outcome": "wrong", "consequence": "If this goes into the DHF and we get audited, the auditor asks: how do you verify ''a long time''? What''s your acceptance criteria? We''d have no answer."}, {"label": "It''s not verifiable — ''long time'' is not measurable. You can''t write a pass/fail test for it.", "outcome": "correct", "consequence": "Right. The core defect is verifiability — every design input must support a clear pass/fail test."}, {"label": "It needs to reference an ISO standard.", "outcome": "wrong", "consequence": "Standards may help, but the root problem is that ''long time'' has no numeric specification. Adding a standard won''t fix that alone."}]}, {"id": "n2", "prompt": "How do you fix DI-007?", "options": [{"label": "Delete it — battery life isn''t a real design input.", "outcome": "wrong", "consequence": "Battery life is a primary clinical user need. Deleting it leaves a verifiability gap, not solves it."}, {"label": "Rewrite: \"The device shall support a minimum of 18 months of continuous operation at the rated duty cycle without battery replacement or recharging.\"", "outcome": "correct", "consequence": "Now testable: power the device, measure runtime under rated duty cycle, pass if ≥18 months extrapolated."}, {"label": "Add a footnote explaining that ''long time'' means 18 months.", "outcome": "wrong", "consequence": "Footnotes don''t replace requirements. An auditor reading DI-007 without the footnote would still find it non-conforming."}]}, {"id": "n3", "prompt": "The corrected DI-007 needs to be entered in the DHF. What else must happen?", "options": [{"label": "Just update the document — no need to notify anyone.", "outcome": "wrong", "consequence": "An uncontrolled change to a design input invalidates everything downstream that traces to it. The change itself must be controlled."}, {"label": "Raise a change to the design input document, have it reviewed and approved by QA, and update the DHF.", "outcome": "correct", "consequence": "Right. Even fixing a defect requires change control because downstream V&V protocols trace back to DI-007."}, {"label": "Email the team and wait for someone to approve it later.", "outcome": "wrong", "consequence": "Email isn''t a controlled approval. The change has to flow through your change-control process."}]}], "debrief": {"flow": ["Flag the vague DI", "Rewrite as quantified, verifiable spec", "Raise change request", "QA review and approval", "Update DHF with new revision", "Notify downstream V&V protocols"], "text": "Vague design inputs are the single biggest source of downstream delays. A correctly written DI lets V&V planning begin immediately. A vague one blocks Gate 3 for weeks while engineers argue about acceptance criteria."}, "colleague_card": "Priya Nair: \"Vague design inputs are the single biggest source of downstream delays I see. Fix it early.\""}, {"id": "t1_3_4", "type": "meeting_simulation", "title": "Design Input Review Meeting", "xp": 250, "scenario": "You''re presenting the CardioSense Pro Design Input Register to Tom (R&D Lead, chair), Priya (QA), and Dr. Rao (Clinical Advisor). Six prompts. You need at least 4 correct for Conditional Pass, all 6 for full approval.", "attendees": [{"name": "Tom Hargreaves", "role": "R&D Lead (chair)", "avatar": "TH"}, {"name": "Priya Nair", "role": "QA Manager", "avatar": "PN"}, {"name": "Dr. Anaya Rao", "role": "Clinical Advisor", "avatar": "AR"}], "beats": [{"id": "b1", "speaker": "Priya Nair", "prompt": "DI-003 says ''the device shall be biocompatible.'' That''s not verifiable — what''s the correct action?", "cards": [{"label": "Reference ISO 10993-1", "body": "I''ll revise DI-003 to reference ISO 10993-1 and specify cytotoxicity, sensitisation, and implantation testing.", "correct": true, "reaction": "Priya: ''Good. Make sure the specific test categories are listed.''"}, {"label": "Defend status quo", "body": "Biocompatibility is well understood — it doesn''t need to be more specific.", "correct": false, "reaction": "Priya: ''It''s not about being understood — it''s about being verifiable.''"}, {"label": "Add a note", "body": "I''ll add a note referencing our materials list.", "correct": false, "reaction": "Priya: ''A note isn''t a requirement. Rewrite the DI itself.''"}]}, {"id": "b2", "speaker": "Dr. Anaya Rao", "prompt": "DI-005 requires transmission within 10 seconds. In hospital imaging suites, that may not be achievable due to RF interference. Should we change it?", "cards": [{"label": "Add exception clause", "body": "Valid concern. I''d add: ''within 10 seconds under standard RF conditions per IEC 60601-1-2, with a documented exception procedure for high-interference environments.''", "correct": true, "reaction": "Dr. Rao: ''That works — the exception procedure is important.''"}, {"label": "Relax to 60 seconds", "body": "Let''s change the spec to 60 seconds to be safe.", "correct": false, "reaction": "Dr. Rao: ''Too lenient clinically — 60 seconds delays time-critical alerts.''"}, {"label": "Defer to post-market", "body": "10 seconds is fine — we''ll deal with edge cases in post-market.", "correct": false, "reaction": "Dr. Rao: ''No. Known risks must be addressed pre-market.''"}]}, {"id": "b3", "speaker": "Tom Hargreaves", "prompt": "DI-002 requires weight <12g. Our battery alone is 9g. Should we revise the weight requirement?", "cards": [{"label": "Investigate before revising", "body": "Before revising DI-002, I''d check if a lighter battery exists or if we can shed weight elsewhere. Changing a design input to fit the current design should be a last resort.", "correct": true, "reaction": "Tom: ''Agreed. Let''s action a mass budget analysis before touching the requirement.''"}, {"label": "Relax weight spec", "body": "Let''s change DI-002 to <20g — gives plenty of headroom.", "correct": false, "reaction": "Tom: ''Not clinically validated. 12g is the comfort threshold from Dr. Rao''s user research.''"}, {"label": "Remove the spec", "body": "Remove the weight requirement — it''s not critical.", "correct": false, "reaction": "Tom: ''It''s traceable to a clinician user need. We can''t just remove it.''"}]}, {"id": "b4", "speaker": "Priya Nair", "prompt": "DI-006 references IEC 60601-1 but doesn''t specify which edition. We need IEC 60601-1:2005+A1:2012.", "cards": [{"label": "Specify edition", "body": "I''ll update DI-006 to explicitly reference IEC 60601-1:2005+A1:2012 and note the applicable test clauses.", "correct": true, "reaction": "Priya: ''Perfect.''"}, {"label": "Edition doesn''t matter", "body": "The edition doesn''t matter — the test lab will know.", "correct": false, "reaction": "Priya: ''It matters. The spec must be unambiguous.''"}, {"label": "Ask the lab", "body": "I''ll ask the test lab which edition they certify to.", "correct": false, "reaction": "Priya: ''The requirement should specify the edition, not delegate it.''"}]}, {"id": "b5", "speaker": "Dr. Anaya Rao", "prompt": "I don''t see a requirement for data storage when wireless transmission fails. Clinically, we cannot lose ECG data.", "cards": [{"label": "Add storage DI", "body": "That''s a gap. I''ll add: ''The device shall store a minimum of 27 days of continuous ECG data in non-volatile onboard memory, independent of wireless connectivity status.''", "correct": true, "reaction": "Dr. Rao: ''27 days gives clinicians adequate follow-up window. Good catch.''"}, {"label": "Assume always connected", "body": "The device should always be connected, so this shouldn''t happen.", "correct": false, "reaction": "Dr. Rao: ''In hospital environments connectivity drops constantly. We cannot lose data.''"}, {"label": "Put it in the IFU", "body": "I''ll add a note in the user manual.", "correct": false, "reaction": "Dr. Rao: ''The user manual is not a design requirements document.''"}]}, {"id": "b6", "speaker": "Tom Hargreaves", "prompt": "We don''t have a requirement for implant depth. Should this be in design inputs?", "cards": [{"label": "IFU not DI", "body": "Implant depth is a clinical use parameter — it belongs in the IFU. The corresponding design input is device geometry that enables correct placement.", "correct": true, "reaction": "Tom: ''Exactly right.''"}, {"label": "Add as DI", "body": "I''ll add ''the device shall be implanted at 5mm depth'' as a design input.", "correct": false, "reaction": "Tom: ''No — surgical depth is a procedure parameter, not a device specification.''"}, {"label": "Surgeon''s decision", "body": "No — implant depth is the surgeon''s decision and shouldn''t be specified.", "correct": false, "reaction": "Tom: ''Partial credit. The IFU still needs to guide the surgeon.''"}]}], "thresholds": {"pass": {"min": 6, "label": "Approved", "text": "All six design input concerns resolved. Design inputs are formally approved and ready for the DHF. Tom signs off as chair, Priya as QA, Dr. Rao as clinical advisor."}, "conditional": {"min": 4, "label": "Conditionally Approved", "text": "Three actions raised: 1) Revise DI-002 pending mass budget analysis, 2) Update DI-003 to reference ISO 10993-1 test categories, 3) Add onboard memory storage design input. Re-review scheduled in 1 week."}, "fail": {"min": 0, "label": "Two Design Inputs Unapproved", "text": "Two design inputs unapproved. Schedule a re-review. The design freeze for Gate 3 will need to be deferred until the inputs are corrected."}}, "colleague_card": {"name": "Tom Hargreaves", "role": "R&D Lead", "avatar": "TH", "quote": "Meeting a clinical reviewer is one of the most challenging parts of the job. You have to speak clinical and engineering simultaneously."}}]}'::jsonb);
INSERT INTO public.lessons (category, path_group, level, order_index, title, description, xp_reward, task_xp_total, colleague_name, colleague_role, content) VALUES ('Biomedical', 'Engineering', 1, 4, 'Stage 1.4 — DHF Setup', 'Build the CardioSense Pro DHF and survive an FDA audit simulation.', 600, 600, 'Priya Nair', 'QA Manager', '{"format": "staged", "stage_label": "Stage 1.4", "team_quotes": [{"name": "Priya Nair", "role": "QA Manager", "avatar": "PN", "quote": "An auditor who can''t find something in your DHF will assume it doesn''t exist."}, {"name": "Marcus Obi", "role": "Document Controller", "avatar": "MO", "quote": "A well-structured DHF index is worth its weight in gold during an audit."}], "scenario": "Time to set up the CardioSense Pro DHF. Priya walks you through what it is and why it matters; you build the index, log your first meeting record, and survive an FDA audit simulation.", "diagram_label": "Design History File — Mandatory Sections", "stages": [{"id": "t1_4_1", "type": "guided_scenario", "title": "The Design History File", "xp": 100, "colleague": {"name": "Priya Nair", "role": "QA Manager"}, "brief": ["The DHF is the complete, organised record of the design and development of a medical device. FDA 21 CFR 820.181 requires it. ISO 13485 clause 7.3 requires it. Your Notified Body will spend the better part of an audit going through it.", "The DHF contains everything: design inputs, outputs, reviews, V&V records, risk management file, change control log, and regulatory correspondence. It''s not a drawer full of paper — it''s a structured, version-controlled, traceable archive proving you followed your development process.", "The DHF belongs to the device, not to the project. It doesn''t end at launch. Post-market complaints, field safety actions, and design changes are all added throughout the device''s commercial life. Think of it as the permanent medical record of the product itself."], "pull_quote": "The DHF belongs to the device, not to the project.", "scenario": "An FDA inspector arrives for a routine inspection. She requests to see the DHF for the CardioSense Pro. You have 15 minutes to produce it.", "questions": [{"id": "q1", "kind": "single_best", "prompt": "Where should the DHF be stored?", "options": [{"label": "In the company''s validated eQMS, with all documents indexed, version-controlled, and access-controlled.", "correct": true, "feedback": "Right. The eQMS provides the single source of truth, audit trail, and access control."}, {"label": "On the R&D team''s shared drive, organised by project folder.", "correct": false, "feedback": "Shared drives are uncontrolled. Documents may be overwritten without audit trails."}, {"label": "In a locked filing cabinet with a paper index.", "correct": false, "feedback": "Impractical for modern inspections and creates significant retrieval risk."}, {"label": "With the project manager, who knows where everything is.", "correct": false, "feedback": "Key-person dependency is a QMS risk. The system must hold the DHF."}]}, {"id": "q2", "kind": "classify", "prompt": "Sort these into: Must be in the DHF or Not required in DHF.", "categories": ["Must be in DHF", "Not required"], "items": [{"text": "Design input document Rev C (approved)", "category": "Must be in DHF"}, {"text": "Engineering sketch (unapproved, for discussion only)", "category": "Not required"}, {"text": "Verification protocol VP-001", "category": "Must be in DHF"}, {"text": "Verification test report TR-001", "category": "Must be in DHF"}, {"text": "An email from Tom discussing a design idea", "category": "Not required"}, {"text": "Risk Management File", "category": "Must be in DHF"}, {"text": "Gate 2 Meeting Record", "category": "Must be in DHF"}, {"text": "The ISO 13485 standard (purchased copy)", "category": "Not required"}, {"text": "CAPA-003 relating to a design change", "category": "Must be in DHF"}, {"text": "The marketing brochure for CardioSense Pro", "category": "Not required"}], "feedback": "The DHF contains controlled, approved records demonstrating the design process was followed. Working documents, informal communications, and external publications are not DHF records."}, {"id": "q3", "kind": "rank_steps", "prompt": "An auditor asks for evidence the CardioSense Pro''s battery life was verified. Put the DHF search steps in order.", "items": ["Open the DHF index in the eQMS", "Navigate to the Verification & Validation section", "Locate the Verification Plan for battery life", "Open the associated Verification Protocol (VP-012)", "Open the Verification Test Report (TR-012) linked from VP-012", "Confirm the pass/fail conclusion and sample size in TR-012", "Show the auditor that TR-012 is signed, dated, and at an approved revision"], "feedback_correct": "Right. Every step traceable, every step in the eQMS, no paper shuffling.", "feedback_incorrect": "Open the DHF index first — that''s the navigation aid. Test report is at the end."}, {"id": "q4", "kind": "fill_blank", "prompt": "Complete FDA 21 CFR 820.181: \"The DHF shall contain or reference the ________ necessary to demonstrate that the design was developed in accordance with the approved design plan.\"", "answer": "records", "alternatives": ["record"], "feedback_correct": "The exact FDA language is ''records.'' This means the DHF can contain references to records stored elsewhere — everything doesn''t have to be physically in one folder, as long as the reference is clear and the record can be retrieved.", "feedback_incorrect": "The exact FDA term is ''records'' — same word, plural."}], "colleague_card": "Priya Nair: \"An auditor who can''t find something in your DHF will assume it doesn''t exist.\""}, {"id": "t1_4_2", "type": "document_builder", "title": "Create the DHF Index", "xp": 150, "instruction": "For each of the 8 mandatory DHF sections, write a 1-sentence scope statement and list at least 2 example documents. Required keywords are listed under each section.", "reference": {"title": "Mandatory DHF Sections — ISO 13485 §7.3 & FDA 21 CFR 820.181", "body": "Every Design History File MUST include sections for:\n1. Design and Development Planning\n2. Design Inputs\n3. Design Outputs\n4. Design Reviews\n5. Design Verification\n6. Design Validation\n7. Design Transfer\n8. Design Changes (Change Control Log)\n9. Risk Management File (per ISO 14971)\n10. Regulatory Correspondence", "highlights": ["ISO 13485 §7.3", "FDA 21 CFR 820.181"]}, "fields": [{"id": "s1", "label": "Section 1 — Design and Development Planning", "placeholder": "Scope: Contains the Design and Development Plan... Examples: Design Plan, Gantt chart", "required_terms": ["Design and Development Plan", "phases", "Gantt"], "min_chars": 60}, {"id": "s2", "label": "Section 2 — Design Inputs", "placeholder": "Scope: Contains all approved design input documents... Examples: Design Input Register, User Needs Document", "required_terms": ["Design Input Register", "User Needs", "requirements"], "min_chars": 60}, {"id": "s3", "label": "Section 3 — Design Outputs", "placeholder": "Scope: Engineering drawings, software specifications, component specs... Examples: Engineering Drawings, SRS", "required_terms": ["Engineering Drawings", "Software Requirements", "specifications"], "min_chars": 60}, {"id": "s4", "label": "Section 4 — Design Reviews", "placeholder": "Scope: Records of all formal design reviews... Examples: Gate Meeting Records, Action Logs", "required_terms": ["Gate Meeting", "Action Log", "design review"], "min_chars": 60}, {"id": "s5", "label": "Section 5 — Design Verification", "placeholder": "Scope: Verification protocols and test reports... Examples: VP-001 to VP-XXX, V&V Traceability Matrix", "required_terms": ["Verification Protocol", "Traceability Matrix", "test reports"], "min_chars": 60}, {"id": "s6", "label": "Section 6 — Design Validation", "placeholder": "Scope: Validation protocols and reports... Examples: Usability Study, Clinical Performance Evaluation", "required_terms": ["Usability", "Clinical Performance", "validation"], "min_chars": 60}, {"id": "s7", "label": "Section 7 — Risk Management File", "placeholder": "Scope: All risk management records per ISO 14971... Examples: Risk Management Plan, Risk Management File, Risk Management Report", "required_terms": ["ISO 14971", "hazard", "Risk Management Report"], "min_chars": 60}, {"id": "s8", "label": "Section 8 — Design Changes / Change Control Log", "placeholder": "Scope: All ECRs and ECOs throughout the product lifecycle... Examples: ECR-001 onwards, ECO-001 onwards", "required_terms": ["Engineering Change Request", "ECR", "ECO"], "min_chars": 60}], "dhf": {"doc_code": "DHF-INDEX-001", "doc_title": "DHF Index — CardioSense Pro", "doc_section": "DHF Master Index"}, "colleague_card": {"name": "Marcus Obi", "role": "Document Controller", "avatar": "MO", "quote": "A well-structured DHF index is worth its weight in gold during an audit. Everything findable in 30 seconds."}}, {"id": "t1_4_3", "type": "document_builder", "title": "Your First DHF Entry", "xp": 150, "instruction": "Log the Design Input Review Meeting from Task 1.3.4 as a formal DHF entry. Each field has required content elements.", "reference": {"title": "Template — DHF Meeting Record", "body": "A DHF meeting record must include:\n• Meeting title and type\n• Date, time, and location\n• Attendees with roles\n• Agenda items reviewed (with disposition for each)\n• Action items (description, owner, due date)\n• Documents affected (with revision)\n• Review status (Approved / Conditionally Approved / Not Approved)", "highlights": ["ISO 13485 §7.3.4", "FDA 21 CFR 820.30(e)"]}, "fields": [{"id": "title_type", "label": "Meeting title and type", "placeholder": "Design Input Review Meeting — CardioSense Pro. Type: Design Review.", "required_terms": ["Design Input Review", "Design Review", "CardioSense Pro"], "min_chars": 50}, {"id": "attendees", "label": "Attendees (3 named with roles)", "placeholder": "Tom Hargreaves — R&D Lead (chair); Priya Nair — QA Manager; Dr. Anaya Rao — Clinical Advisor.", "required_terms": ["Tom Hargreaves", "Priya Nair", "Anaya Rao", "R&D", "QA", "Clinical"], "min_chars": 100}, {"id": "agenda", "label": "Agenda items and dispositions (at least 4)", "placeholder": "DI-003: Conditionally Approved (revised to reference ISO 10993-1). DI-005: Conditionally Approved (RF exception clause added). DI-002: Held — pending mass budget. DI-006: Approved with note.", "required_terms": ["DI-003", "DI-005", "Conditionally Approved", "ISO 10993"], "min_chars": 150}, {"id": "actions", "label": "Action items (at least 3, each with owner and due date)", "placeholder": "1) Revise DI-002 pending mass budget — Tom Hargreaves — Due 2 weeks. 2) Update DI-003 to reference ISO 10993-1 — Owner: You — Due 1 week. 3) Add memory storage DI — Owner: You — Due 1 week.", "required_terms": ["Revise", "Owner", "Due"], "min_chars": 150}, {"id": "disposition", "label": "Overall meeting disposition", "placeholder": "Conditionally Approved — open actions to be closed before re-review.", "required_terms": ["Conditionally Approved", "actions", "re-review"], "min_chars": 40}], "dhf": {"doc_code": "MR-001", "doc_title": "Design Input Review Meeting Record — CardioSense Pro", "doc_section": "Design Reviews"}, "colleague_card": {"name": "Priya Nair", "role": "QA Manager", "avatar": "PN", "quote": "If I opened this record in five years during a post-market audit, I''d know exactly what happened in that meeting. That''s the standard."}}, {"id": "t1_4_4", "type": "decision_sandbox", "title": "DHF Audit Simulation", "xp": 200, "scenario": "Six months after CardioSense Pro launches, an FDA inspector arrives. She requests four specific records from the DHF.", "nodes": [{"id": "r1", "prompt": "REQUEST 1: ''Please show me the approved design input document and traceability matrix.''", "options": [{"label": "Open the Design Input Register Rev C and the V&V Traceability Matrix Rev B from the DHF index.", "outcome": "correct", "consequence": "Right. Both retrieved from controlled storage with current revisions. Inspector ticks the box."}, {"label": "The design inputs are in the engineering drawings.", "outcome": "wrong", "consequence": "Design inputs are a separate controlled document — not embedded in drawings. This is a finding."}, {"label": "I''ll need to ask our R&D Lead — he manages that.", "outcome": "wrong", "consequence": "Key-person dependency is itself a QMS concern. An auditable system must allow anyone with access to retrieve records."}]}, {"id": "r2", "prompt": "REQUEST 2: ''I''d like to see the verification report for the battery life requirement.''", "options": [{"label": "Show TR-012 containing raw data, pass/fail determination, and reference to approved protocol VP-012.", "outcome": "correct", "consequence": "Right. Complete record retrievable, all linkages intact."}, {"label": "Show an email from the test lab saying the battery passed.", "outcome": "wrong", "consequence": "Email is not a controlled quality record. Inspector raises a finding."}, {"label": "Tell the inspector the report is still being written.", "outcome": "wrong", "consequence": "A device cannot launch without complete V&V records. This finding may halt distribution."}]}, {"id": "r3", "prompt": "REQUEST 3: ''Can you show me the most recent CAPA and confirm it''s closed with an effectiveness check?''", "options": [{"label": "Open CAPA-003, show the effectiveness check entry dated 90 days after implementation, plus the QA Manager''s closure signature.", "outcome": "correct", "consequence": "Right. Full CAPA lifecycle documented including post-implementation verification."}, {"label": "''That CAPA is closed — I don''t have the details to hand.''", "outcome": "wrong", "consequence": "Inability to produce records during an inspection IS a finding, even if records exist."}, {"label": "Show CAPA-003 but it has no effectiveness check — closed early.", "outcome": "wrong", "consequence": "Closing a CAPA without an effectiveness check generates an observation. The CAPA isn''t truly closed."}]}, {"id": "r4", "prompt": "REQUEST 4: ''Your change control log shows ECO-007 was implemented 6 months ago. Can you show me the re-verification records?''", "options": [{"label": "Locate ECO-007 → references VP-019 and TR-019 → both complete and approved.", "outcome": "correct", "consequence": "Right. Change control linked to re-verification. Audit trail complete."}, {"label": "''ECO-007 was a minor change — we determined re-verification wasn''t necessary.''", "outcome": "wrong", "consequence": "Wrong unless there''s a documented impact assessment justifying no re-verification. Without it, this is a finding."}, {"label": "''We''ll need to check with the R&D team.''", "outcome": "wrong", "consequence": "DHF must be complete and accessible. Asking the team mid-audit raises concerns about your QMS."}]}], "debrief": {"text": "A well-maintained DHF is your best defence in any audit. Every gap in your DHF is a gap in your traceability. Every gap in traceability is a potential patient safety question."}, "colleague_card": "Priya Nair: \"Level 1 complete. The skills you''ve built here — document control, regulatory thinking, DHF management — are the foundation everything else sits on.\""}]}'::jsonb);
